mod solution;

fn main() {
    let cases = [
    (r#"add4 add9 remove4 add7"#, r#"7,9"#),
    (r#"add1 add2 remove2 add3"#, r#"1,3"#),
    (r#"
add1 add2 remove2 add3
"#, r#"1,3"#),
    (r#"  
add4 add9 remove4 add7
  "#, r#"7,9"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS randomized-set");
}
